import{_ as o,o as c,c as d,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"块驱动","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/driver-block.md","filePath":"zh/l1/driver-block.md"}'),t={name:"zh/l1/driver-block.md"};function r(i,e,l,s,_,n){return c(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="块驱动" tabindex="-1">块驱动 <a class="header-anchor" href="#块驱动" aria-label="Permalink to &quot;块驱动&quot;">​</a></h1><p>一个存储设备家族如何加入块服务，让整个系统（VFS、分区、fs 工具、disk-tool 向导）看见它。</p><h2 id="模型-3-0-0" tabindex="-1">模型（3.0.0） <a class="header-anchor" href="#模型-3-0-0" aria-label="Permalink to &quot;模型（3.0.0）&quot;">​</a></h2><ul><li>驱动住在 <code>ocos/drivers/storage/</code> - 每个家族一对文件 （<code>drv_storage_ahci.{c,h}</code>、<code>drv_storage_nvme.*</code>、 <code>drv_storage_ata*</code>、<code>drv_storage_virtio_blk.*</code>、 <code>drv_storage_scsi*</code>、<code>drv_storage_sdhci.*</code>）。</li><li>身份用 <code>OC_DRIVER_DECL(&quot;block&quot;, &quot;ahci&quot;, &amp;ops, &quot;SATA AHCI&quot;)</code> 声明 - 一个由启动收集器遍历的 const 描述符。没有全局注册表 编辑，没有手工的 init-call 链。</li><li>驱动只能在自己的探测/摘除路径内，通过驱动内部 API （<code>drv_storage_api.h</code>：<code>driver_block_add_device</code> / <code>remove_device</code>；<code>BLK_MAX_DEVICES</code> 个槽、512 字节扇区、32 字符 名字）修改块服务的设备表。寄存器类条目已在 v2.0.0 移除 - 这个 头是内核内部的，不是 L1 表面。</li><li>硬件配置旋钮（<code>CONFIG_NVME</code> / <code>CONFIG_AHCI</code> / <code>CONFIG_VIRTIO_BLK</code>，<code>make defconfig</code> / <code>menuconfig</code>）把单个 家族编译出去；init 调用由 <code>core/generated/config_gen.h</code> 宏 桩化。</li></ul><h2 id="服务侧" tabindex="-1">服务侧 <a class="header-anchor" href="#服务侧" aria-label="Permalink to &quot;服务侧&quot;">​</a></h2><p><code>ocos/services/block/</code> 代理 L1SVC 类别 2 表面：设备列表 （<code>lsblk</code>）、分区表（<code>parted</code>）、mkfs（FAT32 / exFAT / ext4）、 <code>fsck</code>、<code>sync</code>、A/B 盘工具（<code>abdisk</code>、<code>install</code>、 <code>grub-install</code>、<code>abcfg</code>）、磁盘统计，以及测试家族 （<code>ahci_test</code> .. <code>fs_mount_test</code>）。缓存门禁（64 槽）位于服务与 驱动之间。</p><h2 id="一个新家族长什么样" tabindex="-1">一个新家族长什么样 <a class="header-anchor" href="#一个新家族长什么样" aria-label="Permalink to &quot;一个新家族长什么样&quot;">​</a></h2><ol><li><code>ocos/drivers/storage/drv_storage_&lt;fam&gt;.{c,h}</code> - 探测总线、 读容量、每发现一块盘 <code>driver_block_add_device()</code> 一次。</li><li>底部一行 <code>OC_DRIVER_DECL(&quot;block&quot;, &quot;&lt;fam&gt;&quot;, &amp;ops, &quot;description&quot;)</code>。</li><li>服务里一个状态操作（如果这个家族配得上的话），操作号追加到 <code>svc_sysapi_l1svc.h</code>（只许追加！），重新生成镜像 （<code>tools/gen_l1svc_ops.py</code>）。</li><li>应用侧：一个薄包装文件夹或大应用经典表里的一行 （<code>disk-tool</code> 的 <code>g_ops[]</code> 是样板）。</li></ol><h2 id="消费者契约" tabindex="-1">消费者契约 <a class="header-anchor" href="#消费者契约" aria-label="Permalink to &quot;消费者契约&quot;">​</a></h2><p>应用从不触碰驱动：它们调用服务（<code>disk-tool lsblk</code> -&gt; <code>sys_l1svc(BLOCK, LSBLK, ...)</code>）。设备名是稳定契约（<code>hd0</code>、 <code>hd0p1</code>、...）；向导展示 <code>lsblk</code> 并按那种拼法询问名字。</p>',10)])])}const v=o(t,[["render",r]]);export{u as __pageData,v as default};
